begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create function pg_temp.fixture() returns jsonb language plpgsql as $$declare p uuid:=gen_random_uuid();actor uuid;invite uuid:=gen_random_uuid();begin
 actor:=gen_random_uuid();insert into auth.users(id,email)values(actor,actor::text||'@fixture.invalid');update public.profiles set org_id='22222222-2222-2222-2222-222222222222' where id=actor;
 insert into public.properties(id,name,org_id,settings)values(p,'Invitation SQL fixture','22222222-2222-2222-2222-222222222222','{"timezone":"UTC"}');
 return jsonb_build_object('p',p,'actor',actor,'invite',invite,'hash',encode(sha256(convert_to(invite::text,'UTF8')),'hex'));
end$$;
create function pg_temp.create_invite(f jsonb)returns jsonb language sql as $$select public.create_recorded_integration_invite((f->>'p')::uuid,(f->>'actor')::uuid,(f->>'invite')::uuid,'google',array['calendar'],f->>'hash')$$;
create function pg_temp.revoke_invite(f jsonb,id uuid)returns jsonb language sql as $$select public.revoke_recorded_integration_invite((f->>'p')::uuid,(f->>'actor')::uuid,(f->>'invite')::uuid,id)$$;
create function pg_temp.context(f jsonb)returns jsonb language sql as $$select jsonb_build_object('propertyId',f->>'p','profileId',null,'provider','google','capabilities',array['calendar'],'authSource','external_invite','inviteId',f->>'invite','tokenHash',f->>'hash','redirectUri','https://app.invalid/callback','requestedScopes',array['https://www.googleapis.com/auth/calendar'])$$;
create function pg_temp.grant() returns jsonb language sql as $$select jsonb_build_object('accessToken','fixture-access','refreshToken','fixture-refresh','expiresAt',now()+interval '1 hour','accountEmail','fixture@example.invalid','subject','provider-subject','timezone','UTC','scopes',array['https://www.googleapis.com/auth/calendar'],'scopeEvidence','provider_response')$$;
do $$declare f jsonb;r jsonb;again jsonb;decision uuid;auth uuid;ctx jsonb;begin
 f:=pg_temp.fixture();r:=pg_temp.create_invite(f);
 perform pg_temp.check(r->>'state'='created' and r->>'actionEventId'=f->>'invite','creation acknowledges its recorded action');
 perform pg_temp.check(r->'invite'->>'state'='pending','new invitation pending');
 perform pg_temp.check((select count(*)=1 from public.integration_auth_invites where id=(f->>'invite')::uuid),'one link created');
 again:=pg_temp.create_invite(f);perform pg_temp.check(again->>'state'='replayed' and again->'invite'=r->'invite','lost response recovers exact link and original expiry');
 perform pg_temp.check((select count(*)=1 from public.shared_action_events where id=(f->>'invite')::uuid),'recovery records one creation');
 perform pg_temp.check((select action='integration.invite.created' and not training_eligible and not public.shared_action_events.request ? 'token' and not public.shared_action_events.request ? 'tokenHash' and after_state::text not like '%'||(f->>'hash')||'%' from public.shared_action_events where id=(f->>'invite')::uuid),'creation evidence excludes capability secrets and training');
 perform pg_temp.check(pg_temp.create_invite(jsonb_set(f,'{hash}',to_jsonb(repeat('a',64))))->>'state'='link_unavailable','key rotation cannot substitute a different token');
 perform pg_temp.check(public.create_recorded_integration_invite((f->>'p')::uuid,(f->>'actor')::uuid,(f->>'invite')::uuid,'microsoft',array['calendar'],f->>'hash')->>'state'='request_conflict','decision cannot switch provider');
 perform pg_temp.check(public.create_recorded_integration_invite((f->>'p')::uuid,(f->>'actor')::uuid,(f->>'invite')::uuid,'google',array['email'],f->>'hash')->>'state'='request_conflict','decision cannot switch capabilities');
 perform pg_temp.check(pg_temp.create_invite(jsonb_set(f,'{actor}',to_jsonb(gen_random_uuid())))->>'state'='forbidden','creation requires property membership');
 decision:=gen_random_uuid();auth:=gen_random_uuid();ctx:=pg_temp.context(f);
 perform pg_temp.check(public.begin_integration_authorization(auth,ctx)->>'state'='ready','invitation can begin authorization');
 perform pg_temp.check(public.claim_integration_authorization(auth,ctx)->>'state'='claimed','invitation claims provider exchange');
 r:=pg_temp.revoke_invite(f,decision);perform pg_temp.check(r->>'state'='revoked' and r->>'actionEventId'=decision::text,'revocation recorded');
 perform pg_temp.check((select status='blocked' from public.integration_authorizations where id=auth),'revocation cancels claimed authorization');
 perform pg_temp.check(public.finish_integration_authorization(auth,ctx,pg_temp.grant())->>'state'='invite_unavailable','late provider response after revocation cannot connect');
 perform pg_temp.check(not exists(select 1 from public.agent_calendars where property_id=(f->>'p')::uuid),'revoked response creates no connection');
 perform pg_temp.check(pg_temp.revoke_invite(f,decision)->>'replayed'='true','lost revocation response recovers original action');
 perform pg_temp.check((select count(*)=1 from public.shared_action_events where id=decision),'one revocation record');
 perform pg_temp.check(pg_temp.create_invite(f)->>'state'='link_unavailable','revoked link cannot be recovered as active');
 perform pg_temp.check(public.begin_integration_authorization(gen_random_uuid(),ctx)->>'state'='invite_unavailable','revoked link cannot start again');
 perform pg_temp.check(pg_temp.revoke_invite(jsonb_set(f,'{invite}',to_jsonb(gen_random_uuid())),decision)->>'state'='request_conflict','revocation decision cannot target another link');
 perform pg_temp.check(pg_temp.revoke_invite(jsonb_set(f,'{actor}',to_jsonb(gen_random_uuid())),gen_random_uuid())->>'state'='forbidden','revocation checks current membership');
 f:=pg_temp.fixture();perform pg_temp.create_invite(f);update public.integration_auth_invites set expires_at=now()-interval '1 minute' where id=(f->>'invite')::uuid;
 perform pg_temp.check(pg_temp.create_invite(f)->>'state'='link_unavailable','expired recovery cannot extend authority');
 perform pg_temp.check(pg_temp.revoke_invite(f,gen_random_uuid())->>'state'='revoked','expired link can be explicitly revoked');
 f:=pg_temp.fixture();perform pg_temp.create_invite(f);auth:=gen_random_uuid();ctx:=pg_temp.context(f);perform public.begin_integration_authorization(auth,ctx);perform public.claim_integration_authorization(auth,ctx);
 perform pg_temp.check(public.finish_integration_authorization(auth,ctx,pg_temp.grant())->>'state'='saved','valid link authorizes atomically');
 decision:=gen_random_uuid();r:=pg_temp.revoke_invite(f,decision);
 perform pg_temp.check(r->>'state'='already_used','used invitation reports actual result');
 perform pg_temp.check((select phase='failed' and result->>'state'='already_used' from public.shared_action_events where id=decision),'too-late revocation decision recorded as failed');
 perform pg_temp.check((select revoked_at is null and consumed_at is not null from public.integration_auth_invites where id=(f->>'invite')::uuid),'used link stays used');
 perform pg_temp.check((select sync_enabled and access_token='fixture-access' from public.agent_calendars where property_id=(f->>'p')::uuid),'revoking used link never removes connected account');
 perform pg_temp.check(pg_temp.create_invite(f)->>'state'='link_unavailable','used link cannot recover authority');
 f:=pg_temp.fixture();perform pg_temp.create_invite(f);update public.profiles set org_id=null where id=(f->>'actor')::uuid;
 perform pg_temp.check(pg_temp.create_invite(f)->>'state'='forbidden','removed member cannot recover original link');
 perform pg_temp.check(pg_temp.revoke_invite(f,gen_random_uuid())->>'state'='forbidden','removed member cannot revoke link');
 perform pg_temp.check(not has_function_privilege('authenticated','public.create_recorded_integration_invite(uuid,uuid,uuid,text,text[],text)','EXECUTE'),'creation service-only');
 perform pg_temp.check(not has_function_privilege('anon','public.revoke_recorded_integration_invite(uuid,uuid,uuid,uuid)','EXECUTE'),'revocation service-only');
 perform pg_temp.check(not has_table_privilege('authenticated','public.integration_auth_invites','SELECT'),'browser cannot read authority rows');
end$$;
create function pg_temp.reject_action()returns trigger language plpgsql as $$begin if new.action in ('integration.invite.created','integration.invite.revoked') then raise exception 'Fixture recording failure';end if;return new;end$$;
create trigger fixture_invite_failure before insert on public.shared_action_events for each row execute function pg_temp.reject_action();
do $$declare f jsonb;begin
 f:=pg_temp.fixture();begin perform pg_temp.create_invite(f);raise exception 'FAIL: ignored record failure';exception when raise_exception then if SQLERRM<>'Fixture recording failure' then raise;end if;end;
 perform pg_temp.check(not exists(select 1 from public.integration_auth_invites where id=(f->>'invite')::uuid),'creation rolls back if recording fails');
 insert into public.integration_auth_invites(id,property_id,provider,requested_capabilities,token_hash,expires_at,created_by_profile_id)values((f->>'invite')::uuid,(f->>'p')::uuid,'google',array['calendar'],f->>'hash',now()+interval '1 hour',(f->>'actor')::uuid);
 begin perform pg_temp.revoke_invite(f,gen_random_uuid());raise exception 'FAIL: ignored record failure';exception when raise_exception then if SQLERRM<>'Fixture recording failure' then raise;end if;end;
 perform pg_temp.check((select revoked_at is null from public.integration_auth_invites where id=(f->>'invite')::uuid),'revocation rolls back if recording fails');
end$$;
drop trigger fixture_invite_failure on public.shared_action_events;
select count(*) as passed from checks;
rollback;
